\hline
FROM\\TO & \text{仕事 a} & \text{仕事 b} & \text{仕事 c} & \text{仕事 d} \\\hline
\text{仕事 a} & --- & 2 & 1 & 2 \\
\text{仕事 b} & 1 & --- & 1 & 2 \\
\text{仕事 c} & 3 & 2 & --- & 2 \\
\text{仕事 d} & 4 & 3 & 2 & --- \\\hline
\end{tabular}

